const std = @import("std");

pub const env_name: [:0]const u8 = "TF_DS_DRAFT_TAPS_DIRECT";

/// The switch's value: unset, "" or "0" off; "1" on; anything else is a refusal to start (the message is on stderr).
pub fn parse(text: ?[]const u8) ?bool {
    const t = text orelse return false;
    if (t.len == 0 or std.mem.eql(u8, t, "0")) return false;
    if (std.mem.eql(u8, t, "1")) return true;
    std.debug.print("{s}: expected 1 or 0\n", .{env_name});
    return null;
}

pub fn fromText(text: ?[]const u8) error{BadDraftTapsDirect}!bool {
    return parse(text) orelse error.BadDraftTapsDirect;
}

/// The in-place arm's first row's byte address: when window i's rows [taps[i], taps[i] + ns[i] * row_bytes) meet the
/// next window's first row exactly (the items are the round's windows in round order, so consecutive rows mean no
/// window between them was skipped), the whole block is consecutive rows and mainKeys reads it at the taps' row
/// stride. A gap, an overlap, an out-of-order item or an empty list keeps the packing (which preserves the items'
/// order either way).
pub fn inPlace(taps: []const u64, ns: []const usize, row_bytes: usize) ?u64 {
    if (taps.len == 0 or taps.len != ns.len) return null;
    for (0..taps.len - 1) |i| {
        if (taps[i + 1] != taps[i] + ns[i] * row_bytes) return null;
    }
    return taps[0];
}

// -- host reference and tests ---------------------------------------------------------------------------------------
//
// The arm's row addressing on the host, against the packed copy the off path runs (each window's rows gathered in
// window order into one block): the rows mainKeys consumes, byte for byte over a synthetic taps buffer. The launch
// the arm removes (copyRows) is a byte-exact row copy, so the packed gather is the reference; both arms must give
// mainKeys the same bytes.

const expectEqual = std.testing.expectEqual;

test "the switch parses its forms and nothing else" {
    try expectEqual(false, parse(null).?);
    try expectEqual(false, parse("").?);
    try expectEqual(false, parse("0").?);
    try expectEqual(true, parse("1").?);
    try expectEqual(@as(?bool, null), parse("2"));
    try expectEqual(@as(?bool, null), parse("yes"));
    try expectEqual(@as(?bool, null), parse("01"));
    try std.testing.expectEqual(@as(bool, true), try fromText("1"));
    try std.testing.expectError(error.BadDraftTapsDirect, fromText("2"));
}

test "inPlace takes only consecutive windows in their given order" {
    const rb = 64;
    // one window, any length
    const one_n = [_]usize{7};
    const one_t = [_]u64{1000};
    try expectEqual(@as(?u64, 1000), inPlace(&one_t, &one_n, rb));
    // adjacent windows (3 + 2 rows), and a zero-row window meeting both
    const adj_t = [_]u64{ 1000, 1000 + 3 * rb, 1000 + 5 * rb };
    const adj_n = [_]usize{ 3, 2 };
    try expectEqual(@as(?u64, 1000), inPlace(adj_t[0..2], adj_n[0..2], rb));
    const z_t = [_]u64{ 1000, 1000 + 3 * rb, 1000 + 3 * rb };
    const mid_n = [_]usize{ 3, 0, 2 };
    try expectEqual(@as(?u64, 1000), inPlace(&z_t, &mid_n, rb));
    // a one-row gap, an overlap and an out-of-order item each keep the packing
    const gap_t = [_]u64{ 1000, 1000 + 8 * rb };
    const gap_n = [_]usize{ 7, 5 };
    try expectEqual(@as(?u64, null), inPlace(&gap_t, &gap_n, rb));
    const over_t = [_]u64{ 1000, 1000 + 6 * rb };
    try expectEqual(@as(?u64, null), inPlace(&over_t, &gap_n, rb));
    const back_t = [_]u64{ 1000 + 7 * rb, 1000 };
    try expectEqual(@as(?u64, null), inPlace(&back_t, &gap_n, rb));
    // no windows, or counts that do not pair with the rows
    try expectEqual(@as(?u64, null), inPlace(&.{}, &.{}, rb));
    try expectEqual(@as(?u64, null), inPlace(&one_t, &gap_n, rb));
    try expectEqual(@as(?u64, null), inPlace(&one_t, &.{}, rb));
}

test "the in-place rows match the packed copy byte for byte (1-4 windows, lengths 1-7)" {
    const W = 8; // the taps' row width in u16 (a small taps * D)
    const rb = W * 2;
    var taps: [64][W]u16 = undefined;
    for (&taps, 0..) |*rowv, r| {
        for (rowv, 0..) |*v, c| {
            v.* = @intCast(r * W + c);
        }
    }
    const base: u64 = 0x1000; // the taps' byte address (inPlace does the addressing on bytes, as the arm does)
    for (1..5) |k| {
        for (1..8) |a| for (1..8) |b| for (1..8) |c| for (1..8) |d| {
            const lens = [4]usize{ a, b, c, d };
            // the round's layouts: the windows at consecutive rows, then a one-row gap before each window after the
            // first (a non-participating window between them)
            for ([_]bool{ true, false }) |adjacent| {
                var first: [4]u64 = undefined;
                var ns: [4]usize = undefined;
                var row: usize = 0;
                var total: usize = 0;
                for (0..k) |i| {
                    if (i > 0 and !adjacent) row += 1;
                    first[i] = base + row * rb;
                    ns[i] = lens[i];
                    row += lens[i];
                    total += lens[i];
                }
                const got = inPlace(first[0..k], ns[0..k], rb);
                if (!adjacent) {
                    if (k == 1) continue; // one window: no gap to place
                    try expectEqual(@as(?u64, null), got);
                    continue;
                }
                // the packed gather (the off path's copyRows, byte for byte) against the in-place block
                var at: [64][W]u16 = undefined;
                var out: usize = 0;
                for (0..k) |i| {
                    const src_row = @as(usize, @intCast((first[i] - base) / rb));
                    for (0..ns[i]) |r| {
                        at[out] = taps[src_row + r];
                        out += 1;
                    }
                }
                const gfirst = @as(usize, @intCast((got.? - base) / rb));
                for (0..total) |r| try std.testing.expectEqualSlices(u16, &at[r], &taps[gfirst + r]);
            }
        };
    }
}

